const n=document.querySelectorAll(".reveal");if(n.length){const e=new IntersectionObserver(t=>{t.forEach(r=>{r.isIntersecting&&(r.target.classList.add("is-visible"),e.unobserve(r.target))})},{threshold:0,rootMargin:"0px 0px -10% 0px"});n.forEach(t=>e.observe(t))}const o=document.querySelector(".menu-toggle"),s=document.querySelectorAll(".nav");o?.addEventListener("click",()=>{const e=o.getAttribute("aria-expanded")==="true";o.setAttribute("aria-expanded",String(!e)),s.forEach(t=>t.classList.toggle("nav-open",!e))});
